var i=`0821-likhobe`;var n=`world-0821`;var s=`LS`;var a=`southern-africa`;var o=4;var r=611;var l={en:`Likhobe`,ua:`Ліхобе`};var d={en:`Likhobe is a Lesotho dish made with dry white beans, hominy, yellow onion, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Ліхобе, страва кухні країни Лесото. Основні складники: суха біла квасоля, ніштамалізована кукурудза, жовта цибуля, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Soak dried legumes in plenty of cool water for 480 minutes, then drain and discard the soaking water. Cook them fully in fresh water.`,ua:`Замочіть сухі бобові у великій кількості прохолодної води на 480 хвилин, потім злийте та вилийте воду від замочування. Повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:480,i:[[`dry-white-beans`,210,`g`],[`water`,800,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 75 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 75 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:75,i:[[`water`,1e3,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`hominy`,260,`g`],[`water`,700,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,165,`g`],[`tomato`,220,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 16 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 16 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:16,i:[[`table-salt`,null,`to_taste`],[`crushed-red-pepper`,3,`g`]]}];var u={slug:i,id:n,country:`LS`,region:a,servings:4,minutes:611,title:l,text:d,steps:m};export{s as country,u as default,n as id,r as minutes,a as region,o as servings,i as slug,m as steps,d as text,l as title};